The $p$-radial defocusing Klein-Gordon equation on $\mathbb{R}^{3}$
is globally well-posed in $ H^{s} \times H^{s-1} $, $ 1 > s > s(p)$
and there exists a scattering state $\left( u_{+,0}, u_{+,1} \right)
\in H^{s} \times H^{s-1}$ such that

\begin{equation}
\begin{array}{ll}
\lim \limits_{T \rightarrow \infty} \| \left( u(T) , \partial_{t}
u(T) \right) - K(T) ( u_{+,0}, \,  u_{+,1} ) \|_{H^{s} \times H^{s-1}}
& = 0
\end{array}
\label{Eqn:ScatteringRes}
\end{equation}
with

\begin{equation}
K(t):= \left(
\begin{array}{lll}
\cos{(t \langle D \rangle)} & & \frac{ \sin {(t \langle D
\rangle)}}{\langle D \rangle} \\
- \langle D \rangle \sin { t \langle D \rangle} & &  \cos{ (t
\langle D \rangle)}
\end{array}
\right)
\end{equation}
$3<p<5$ and

\begin{equation}
\begin{array}{ll}
s_{p} & := \left\{
\begin{array}{l}
1 - \frac{(5-p)(p-3)}{2(p-1)(p-2)}, \,  3< p \leq 4 \\
1 - \frac{(5-p)^{2}}{2(p-1)(6-p)}, \, 4 \leq p < 5
\end{array}
\right.
\end{array}
\end{equation}
\label{Thm:Scat}

{\textbf{"Strichartz estimates for Klein-Gordon equations in $L_{t}^{q} L_{x}^{r}$ spaces"}}
Assume that $u$ satisfies the following Klein-Gordon equation on
$\mathbb{R}^{d}$, $d \geq 3$

\begin{equation}
\left\{
\begin{array}{ccl}
\partial_{tt} u  - \Delta u + u & = & Q \\
u(0,x)& = & u_{0}(x)    \\
\partial_{t} u(0,x) & = & u_{1}(x)
\end{array}
\right. \label{Eqn:KlGH}
\end{equation}
Let $T \geq 0$. Then

\begin{equation}
\begin{array}{l}
\| u \|_{L_{t}^{q}([0,T]) L_{x}^{r}} + \| \partial_{t} \langle D
\rangle^{-1} u \|_{L_{t}^{q}([0, \,T]) L_{x}^{r}} +  \| u
\|_{L_{t}^{\infty} \left( [0, \, T], \,
H^{m} \right)} +  \| \partial_{t} u \|_{L_{t}^{\infty} \left( [0, \, T], \, H^{m-1}  \right)} \\ \\
\lesssim \| u_{0} \|_{H^{m}} + \| u_{1} \|_{H^{m-1}} + \| Q
\|_{L_{t}^{\tilde{q}}([0,T]) L_{x}^{\tilde{r}}}
\end{array}
\label{Eqn:StrNlkg}
\end{equation}
under the following assumptions

\begin{itemize}

\item $(q,r)$ is $m$- wave admissible, i.e $(q,r)$  lies in the set $\mathcal{W}$ of wave-admissible points

\begin{equation}
\begin{array}{ll}
\mathcal{W} & := \left\{ (q,r): (q,r) \in (2, \infty] \times [2,
\infty), \, \frac{1}{q} + \frac{d-1}{2r} \leq \frac{d-1}{4}
\right\}
\end{array}
\label{Eqn:Waveadm}
\end{equation}
it obeys the following constraint

\begin{equation}
\begin{array}{ll}
\frac{1}{q} + \frac{d}{r} & =\frac{d}{2} -m
\end{array}
\label{Eqn:qrscal}
\end{equation}
and

\begin{equation}
\begin{array}{ll}
(q,r) & \neq \left( 2, \, \frac{2(d-1)}{d-3}  \right)
\end{array}
\label{Eqn:EdPt}
\end{equation}

\item $(\tilde{q},\tilde{r})$ lies in the dual set $\widetilde{\mathcal{W}}$ of $\mathcal{W}$ i.e

\begin{equation}
\begin{array}{ll}
\widetilde{\mathcal{W}} & := \left\{ (\tilde{q},\tilde{r}):
\frac{1}{\tilde{q}} + \frac{1}{q}=1, \, \frac{1}{\tilde{r}} +
\frac{1}{r}=1 \right\}
\end{array}
\end{equation}
and it satisfies the following inequality

\begin{equation}
\begin{array}{ll}
\frac{1}{\tilde{q}} + \frac{d}{\tilde{r}} -2   & = \frac{1}{q} +
\frac{d}{r}
\end{array}
\label{Eqn:ScalingInhomqtildeq}
\end{equation}

\end{itemize}

\label{prop:StrEstLtqLxr}

{"\textbf{Mollified energy at time $0$ is bounded by $N^{2(1-s)}$}"}
Assume that $s_{c} < s < 1$. Then

\begin{equation}
\begin{array}{ll}
E(Iu_{0}) & \lesssim N^{2(1-s)} \left( \| u_{0} \|^{2}_{H^{s}} + \|
u_{1} \|^{2}_{H^{s-1}} + \| u_{0} \|^{p+1}_{H^{s}} \right)
\end{array}
\end{equation}
\label{Prop:EstInitMolNrj}

{\textbf{"Local Boundedness"}}
Assume that $u$ satisfies (\ref{Eqn:NlkgWdat}). Let
$\mathcal{M}=[0,s] \cup \{ 1- \} $. There exists $N= N(\| u_{0}
\|_{H^{s}}, \| u_{1} \|_{H^{s-1}}) \gg 1$ such that if $J$, time
interval, satisfies

\begin{equation}
\begin{array}{ll}
\sup_{t \in J} E(Iu(t)) & \leq 3 E(Iu_{0})
\end{array}
\label{Eqn:InducNrj}
\end{equation}
and

\begin{equation}
\begin{array}{ll}
\| I u \|_{L_{t}^{p+2}(J) L_{x}^{p+2}} & \leq   \frac{1}{
N^{+}\left( E(Iu_{0}) \right)^{\frac{1- \theta_{2}}{2 \theta_{2}}}}
\end{array}
\label{Eqn:LocLong}
\end{equation}
then

\begin{equation}
\begin{array}{ll}
Z(J,u) & \lesssim E^{\frac{1}{2}}(Iu_{0})
\end{array}
\label{Eqn:BoundZ}
\end{equation}
where, given a function $v$,

\begin{equation}
\begin{array}{ll}
Z(J,v) & := \sup_{m \in \mathcal{M}} Z_{m,s}(J,v)
\end{array}
\end{equation}
and

\begin{equation}
\begin{array}{ll}
Z_{m,s}(J,v) & := \sup_{ (q,r)-m \, wave \, adm}  \| \partial_{t}
\langle D \rangle ^{-m} I v \|_{L_{t}^{q}(J) L_{x}^{r}} + \| \langle
D \rangle^{1-m} I v \|_{L_{t}^{q}(J) L_{x}^{r}}
\end{array}
\end{equation}
We recall that, if $a$ and $M$ are two real number, then
$M^{a+}:=M^{a+ \alpha}$ and $M^{a-}:=M^{a - \alpha}$ for $ 0 < \alpha \ll
1$. \label{prop:LocalBd}

{\textbf{"Almost Conservation Law "}}
Assume that $u$ satisfies (\ref{Eqn:NlkgWdat}). Let $J=[a,b]$ be a
time interval. Let $3 \leq p < 5$ and $s \geq \frac{3p-5}{2p}$.
Then

\begin{equation}
\begin{array}{ll}
\left| \sup_{t \in J} E(Iu(t)) - E(Iu(a)) \right| & \lesssim
\frac{Z^{p+1}(J,u)}{N^{\frac{5-p}{2}-}}
\end{array}
\label{Eqn:Acl}
\end{equation}
                                                                
               

 \label{Prop:Acl}

{\textbf{"Estimate of integrals"}}
Let $J$ be a time interval. Let $v$ be a function. Then for $i=1,2$
we have

\begin{equation}
\begin{array}{ll}
| R_{i}(J,v) | & \lesssim \frac{Z^{p+1}(J,v)}{N^{\frac{5-p}{2}-}}
\end{array}
\label{Eqn:BdRi}
\end{equation}
with

\begin{equation}
\begin{array}{ll}
R_{1}(J,v) : = \int_{J} \int_{\mathbb{R}^{3}} \frac{\nabla
Iv(t,x).x}{|x|} \left( F(Iv) - I F(v) \right) \, dx dt
\end{array}
\end{equation}
and

\begin{equation}
\begin{array}{ll}
R_{2}(J,v) := \int_{J} \int_{\mathbb{R}^{3}} \frac{Iv(t,x)}{|x|}
\left( F(Iv) - I F(v) \right) \, dx dt
\end{array}
\end{equation}
\label{Prop:EstInt}

{\textbf{"Almost Morawetz-Strauss Estimate"}}
Let $u$ be a solution of (\ref{Eqn:NlkgWdat}) and let $T \geq 0$.
Then
\begin{equation}
\begin{array}{ll}
\int_{0}^{T} \int_{\mathbb{R}^{3}} \frac{|Iu(t,x)|^{p+1}}{|x|} \, dx
dt & \lesssim \sup_{t \in [0,  T]} E(Iu(t)) + R_{1}([0, \, T],u) +
R_{2}([0, \, T],u)
\end{array}
\label{Eqn:AlmMorStrEst}
\end{equation}
\label{Prop:AlmMor}

Let $x(t)$ be a nonnegative continuous function of time $t$ such
that $x(0)=0$. Let $X$ be a positive constant and let $\alpha_{i},
\, C_{i}$, $i \in \{ 1,..,m \}$ be nonnegative constants such that

\begin{equation}
\begin{array}{ll}
C_{i} X^{\alpha_{i}-1} & \ll 1
\end{array}
\end{equation}
and

\begin{equation}
\begin{array}{ll}
x(t) & \lesssim X +  \displaystyle {\sum_{i=1}^{m}} C_{i}
x^{\alpha_{i}}(t)
\end{array}
\end{equation}
Then

\begin{equation}
\begin{array}{ll}
x(t) & \lesssim X
\end{array}
\label{Eqn:ResLem}
\end{equation}
\label{lem:LgCont}

Let $G$ such that $\| G \|_{L_{t}^{\infty}(J) L_{x}^{2}} \lesssim
Z(J,v)$. If $s \geq \frac{3p-5}{2p}
> s_{c}$ and $3
\leq p < 5$ then

\begin{equation}
\begin{array}{ll}
 \int_{J} \int_{\mathbb{R}^{3}} \left| G \,  ( F(Iv) - IF(v)) \right|     \, dx  dt  & \lesssim \frac{
 Z^{p+1}(J,v)}{N^{\frac{5-p}{2}-}}
\end{array}
\end{equation}
\label{lem:LemVar}
